/** Describes TaggedUrn.Exec.Wf for polymorphic functions. */
export function wfType() {
  return new L.Type(
    L.inductiveExpr(21),
    (w, v) => {
      if (!(v instanceof Wf)) throw new L.MalformedError("not a TaggedUrn.Exec.Wf");
      L.OPAQUE.encode(w, v);
    },
    (r) => new Wf(r.program, r.u64()),
  );
}

/** Describes CapDAG.Grade for polymorphic functions. */
export function gradeType() {
  return new L.Type(
    L.inductiveExpr(22),
    (w, v) => {
      if (typeof v !== "object" || v === null) throw new L.MalformedError("not a CapDAG.Grade");
      switch (v.kind) {
        case "exact":
          w.u32(0);
          return;
        case "guaranteed":
          w.u32(1);
          return;
        case "possible":
          w.u32(2);
          return;
        case "none":
          w.u32(3);
          return;
        default:
          throw new L.MalformedError(`${String(v.kind)} is not a constructor of CapDAG.Grade`);
      }
    },
    (r) => {
      const c = r.u32();
      switch (c) {
        case 0: return ({ kind: "exact" });
        case 1: return ({ kind: "guaranteed" });
        case 2: return ({ kind: "possible" });
        case 3: return ({ kind: "none" });
        default: throw new L.MalformedError(`constructor index ${c} of CapDAG.Grade`);
      }
    },
  );
}

/** Describes TaggedUrn.Constraint for polymorphic functions. */
export function constraintType() {
  return new L.Type(
    L.inductiveExpr(23),
    (w, v) => {
      if (typeof v !== "object" || v === null) throw new L.MalformedError("not a TaggedUrn.Constraint");
      switch (v.kind) {
        case "missing":
          w.u32(0);
          return;
        case "unconstrained":
          w.u32(1);
          return;
        case "optionalNot":
          w.u32(2);
          L.STRING.encode(w, v.value);
          return;
        case "present":
          w.u32(3);
          return;
        case "presentNot":
          w.u32(4);
          L.STRING.encode(w, v.value);
          return;
        case "exact":
          w.u32(5);
          L.STRING.encode(w, v.value);
          return;
        case "absent":
          w.u32(6);
          return;
        default:
          throw new L.MalformedError(`${String(v.kind)} is not a constructor of TaggedUrn.Constraint`);
      }
    },
    (r) => {
      const c = r.u32();
      switch (c) {
        case 0: return ({ kind: "missing" });
        case 1: return ({ kind: "unconstrained" });
        case 2: return ({ kind: "optionalNot", value: L.STRING.decode(r) });
        case 3: return ({ kind: "present" });
        case 4: return ({ kind: "presentNot", value: L.STRING.decode(r) });
        case 5: return ({ kind: "exact", value: L.STRING.decode(r) });
        case 6: return ({ kind: "absent" });
        default: throw new L.MalformedError(`constructor index ${c} of TaggedUrn.Constraint`);
      }
    },
  );
}

/** Describes CapDAG.Bifaci.Pools.Pool for polymorphic functions. */
export function poolType() {
  return new L.Type(
    L.inductiveExpr(24),
    (w, v) => {
      if (typeof v !== "object" || v === null) throw new L.MalformedError("not a CapDAG.Bifaci.Pools.Pool");
      w.u32(0);
      L.STRING.encode(w, v.name);
      L.NAT.encode(w, v.capacity);
      L.NAT.encode(w, v.active);
    },
    (r) => {
      const c = r.u32();
      if (c !== 0) throw new L.MalformedError(`constructor index ${c} of CapDAG.Bifaci.Pools.Pool`);
      return ({ name: L.STRING.decode(r), capacity: L.NAT.decode(r), active: L.NAT.decode(r) });
    },
  );
}

/** Describes CapDAG.Exec.WfAsk for polymorphic functions. */
export function wfAskType() {
  return new L.Type(
    L.inductiveExpr(25),
    (w, v) => {
      if (typeof v !== "object" || v === null) throw new L.MalformedError("not a CapDAG.Exec.WfAsk");
      switch (v.kind) {
        case "unknown":
          w.u32(0);
          return;
        case "within":
          w.u32(1);
          wfType().encode(w, v.u);
          return;
        case "covers":
          w.u32(2);
          wfType().encode(w, v.u);
          return;
        case "same":
          w.u32(3);
          wfType().encode(w, v.u);
          return;
        default:
          throw new L.MalformedError(`${String(v.kind)} is not a constructor of CapDAG.Exec.WfAsk`);
      }
    },
    (r) => {
      const c = r.u32();
      switch (c) {
        case 0: return ({ kind: "unknown" });
        case 1: return ({ kind: "within", u: wfType().decode(r) });
        case 2: return ({ kind: "covers", u: wfType().decode(r) });
        case 3: return ({ kind: "same", u: wfType().decode(r) });
        default: throw new L.MalformedError(`constructor index ${c} of CapDAG.Exec.WfAsk`);
      }
    },
  );
}

