/** Instantiates the program; `options.host` implements its externs. */
export async function load(options = {}) {
  const program = await L.Program.load(options.module ?? (await programModule()), { wasi: options.wasi });
  program.types("capdagFormal__types");
  return new CapdagFormal(program);
}
